insert into public.source_documents (source_type, title, issuance_code, source_url, published_on, publisher, retrieved_on, content_hash, verification_status)
values ('curriculum_guide', 'MATATAG Makabansa CG 2023 Grades 1-3', null, 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20Makabansa%20CG%202023%20Grades%201-3.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides', null, 'Department of Education', '2026-08-11', '0e6521c06ad0bef218a26a2c9b1becdb8daafbeb783f1afb92da11fdf18dc35c', 'verified')
on conflict (source_url) where source_url is not null do update set
  title = excluded.title,
  issuance_code = excluded.issuance_code,
  published_on = excluded.published_on,
  publisher = excluded.publisher,
  retrieved_on = excluded.retrieved_on,
  content_hash = excluded.content_hash,
  verification_status = 'verified',
  updated_at = timezone('utc', now());

insert into public.curriculum_versions (code, name, framework, effective_from_school_year, effective_to_school_year, status, implementation_notes)
values ('REVISED-K10-MATATAG', 'Revised K to 10 / MATATAG Curriculum', 'Revised K to 10 Curriculum', '2024-2025', null, 'active', 'Official source sequence is preserved as curriculum quarters/themes; school grading-period mapping remains separate.')
on conflict (code) do update set
