insert into public.source_documents (source_type, title, issuance_code, source_url, published_on, publisher, retrieved_on, content_hash, verification_status)
values ('curriculum_guide', 'MATATAG Mathematics CG 2023 Grades 1-10', null, 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20Mathematics%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides', null, 'Department of Education', '2026-08-11', 'aee8e63e6136e6c4ea7c90649a35e21c824c7db79c279f9f41e324f2e8118eac', 'verified')
on conflict (source_url) where source_url is not null do update set
  title = excluded.title,
  issuance_code = excluded.issuance_code,
  published_on = excluded.published_on,
  publisher = excluded.publisher,
  retrieved_on = excluded.retrieved_on,
  content_hash = excluded.content_hash,
  verification_status = 'verified',
  updated_at = timezone('utc', now());

