update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = null,
  competency_text = 'Nasusuri ang mga detalye ng tekstong pampanitikan para sa kritikal na pag-unawa Obra Maestra: El Filibusterismo • Pag-aalay sa El Filibusterismo • Ang GOMBURZA • Mga Tauhan • Pagbabalik-tanaw sa Noli Me Tangere (mahahalagang pangyayari na iniuugnay sa El Filibusterismo) • Kabanata 1-10 • Kabanata 11-18 • Kabanata 19-25 • Kabanata 26-32 • Kabanata 33-39 (a) Natutukoy ang mahahalagang elemento (tauhan, tagpuan, banghay na tuon sa tunggalian) at detalye sa El Filibusterimo (b) Naipaliliwanag ang banghay (gaya ng pagkakasunod-sunod ng pangyayari; pagyuyugto ng mga pangyayari (foreshadowing), pagkakahanay ng mga pangyayari (parallelism and simultaneity), at pagbabalik-tanaw sa mga pangyayari (in medias res), mensahe, pahiwatig at kaisipan sa El Filibusterimo (c) Naiuugnay ang mahahalagang kaisipan ng El Filibusterismo batay sa sariling pananaw, moral, katangian at karanasan ng tao (d) Nasusuri ang mahalagang pangyayari ng teksto (tuluyan) batay sa konteksto ng panahon, lunan at may-akda (e) Nasusuri ang mga elementong panlingguwistika sa El Filibusterimo (f) Nakapaghahambing ng mga tekstong hawig sa El Filibusterismo at iba pang nobelang panlipunan na nasusulat sa Pilipinas at sa ibang bansa',
  source_page = 162,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20FILIPINO%20CG%202023%20Grades%202-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 10'
  and cs.name = 'Filipino'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 2;

